from decimal import Decimal, InvalidOperation
from typing import Any


def parse_order(payload: dict[str, Any]) -> dict[str, Any]:
    try:
        discount_percent = Decimal(str(payload.get("discount_percent", 0)))
    except (InvalidOperation, ValueError) as exc:
        raise ValueError("discount_percent must be between 0 and 100") from exc
    if not discount_percent.is_finite() or not Decimal("0") <= discount_percent <= Decimal("100"):
        raise ValueError("discount_percent must be between 0 and 100")
    return {"items": payload["items"], "discount_percent": discount_percent}

